const clientScript = "const donors=[['María González',100,'hoy'],['Carlos Ramírez',25,'hoy'],['Lucía Fernández',50,'hoy'],['Javier Morales',25,'hoy'],['Sofía Herrera',25,'hoy'],['Andrés Vargas',100,'hoy'],['Camila Torres',25,'hoy'],['Diego Castillo',50,'hoy'],['Valentina Ruiz',25,'hoy'],['Miguel Ortega',25,'hoy'],['Isabella Pérez',25,'hoy'],['Rodrigo Mendoza',50,'hoy'],['Daniela Rojas',25,'hoy'],['Fernando Silva',25,'hoy'],['Gabriela Ávila',25,'ayer'],['Pablo Cárdenas',25,'ayer'],['Elena Navarro',25,'ayer'],['Sebastián Ríos',25,'ayer'],['Paula Delgado',25,'ayer'],['Ricardo Aguilar',25,'ayer'],['Natalia Soto',25,'ayer'],['Alejandro Vega',25,'ayer'],['Mónica Salinas',25,'ayer'],['Tomás Guzmán',25,'ayer'],['Renata Peña',25,'ayer'],['Hugo Bautista',25,'ayer'],['Carolina Ibarra',25,'ayer'],['Óscar Miranda',25,'ayer']];\nconst list=document.querySelector('#donors');\nlist.innerHTML=donors.map(([name,amount,ago])=>`<li><span class=\"donor-left\"><span class=\"avatar\">${name[0]}</span><span class=\"donor-name\">${name}<small class=\"ago\">${ago}</small></span></span><b class=\"donor-amount\">$${amount}</b></li>`).join('');\n\nconst modal=document.querySelector('#donation-modal');\nconst openModal=()=>{modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.style.overflow='hidden'};\nconst closeModal=()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.style.overflow=''};\ndocument.querySelectorAll('[data-donate]').forEach(button=>button.addEventListener('click',openModal));\ndocument.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',closeModal));\ndocument.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal()});\n\nconst amountButtons=[...document.querySelectorAll('.amounts button')];\nconst continueButton=document.querySelector('#continue');\nconst customInput=document.querySelector('.custom input');\namountButtons.forEach(button=>button.addEventListener('click',()=>{amountButtons.forEach(item=>item.classList.remove('selected'));button.classList.add('selected');customInput.value='';continueButton.textContent=`Continuar con ${button.textContent}`}));\ncustomInput.addEventListener('input',()=>{amountButtons.forEach(item=>item.classList.remove('selected'));continueButton.textContent=`Continuar con $${customInput.value||'0'}`});\n\nconst toast=document.querySelector('#toast');\nconst showToast=(message,duration=3600)=>{toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),duration)};\nconst selectedAmount=()=>{const preset=document.querySelector('.amounts button.selected');return customInput.value?Number(customInput.value):Number(preset?.textContent.replace('$','')||0)};\ncontinueButton.addEventListener('click',async()=>{\n  const amount=selectedAmount();\n  if(!Number.isFinite(amount)||amount<1||amount>5000){showToast('Elige un valor entre $1 y $5,000.');return}\n  const originalLabel=continueButton.textContent;\n  continueButton.disabled=true;\n  continueButton.textContent='Abriendo Stripe…';\n  try{\n    const response=await fetch('/api/create-checkout-session',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({amount})});\n    const data=await response.json();\n    if(!response.ok||!data.url)throw new Error(data.error||'No fue posible iniciar el pago.');\n    window.location.assign(data.url);\n  }catch(error){showToast(error.message||'No fue posible iniciar el pago.');continueButton.disabled=false;continueButton.textContent=originalLabel}\n});\nconst paymentState=new URLSearchParams(window.location.search).get('donation');\nif(paymentState==='success')showToast('¡Gracias! Stripe confirmó el regreso del Checkout.',5000);\nif(paymentState==='cancelled')showToast('El pago fue cancelado. Puedes intentarlo nuevamente.');\ndocument.querySelector('#cookies').addEventListener('click',()=>{toast.textContent='Preferencias de cookies abertas em modo demonstrativo.';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)});\n";

const securityHeaders = {
  "referrer-policy": "strict-origin-when-cross-origin",
  "x-content-type-options": "nosniff",
  "x-frame-options": "SAMEORIGIN",
};

function response(body, init = {}) {
  const headers = new Headers(init.headers || {});
  for (const [name, value] of Object.entries(securityHeaders)) headers.set(name, value);
  return new Response(body, { ...init, headers });
}

function json(data, status = 200) {
  return response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}

async function createCheckoutSession(request, env) {
  if (!env.STRIPE_SECRET_KEY) {
    return json({ error: "O pagamento ainda não foi configurado. Adicione STRIPE_SECRET_KEY nas variáveis do Site." }, 503);
  }

  let payload;
  try {
    payload = await request.json();
  } catch {
    return json({ error: "Pedido inválido." }, 400);
  }

  const amount = Number(payload.amount);
  if (!Number.isFinite(amount) || amount < 1 || amount > 5000 || Math.round(amount * 100) !== amount * 100) {
    return json({ error: "Escolha um valor entre US$ 1 e US$ 5.000." }, 400);
  }

  const origin = new URL(request.url).origin;
  const params = new URLSearchParams();
  params.set("mode", "payment");
  params.set("submit_type", "donate");
  params.set("success_url", `${origin}/?donation=success&session_id={CHECKOUT_SESSION_ID}`);
  params.set("cancel_url", `${origin}/?donation=cancelled`);
  params.set("line_items[0][price_data][currency]", "usd");
  params.set("line_items[0][price_data][product_data][name]", "Donación para la operación de Jhoel");
  params.set("line_items[0][price_data][product_data][description]", "Aporte solidario para la operación, exámenes y recuperación de Jhoel");
  params.set("line_items[0][price_data][unit_amount]", String(Math.round(amount * 100)));
  params.set("line_items[0][quantity]", "1");
  params.set("metadata[campaign]", "jhoel");

  const stripeResponse = await fetch("https://api.stripe.com/v1/checkout/sessions", {
    method: "POST",
    headers: {
      authorization: `Bearer ${env.STRIPE_SECRET_KEY}`,
      "content-type": "application/x-www-form-urlencoded",
    },
    body: params,
  });

  const stripePayload = await stripeResponse.json().catch(() => null);
  if (!stripeResponse.ok || !stripePayload?.url) {
    const message = stripePayload?.error?.message || "Não foi possível iniciar o Checkout do Stripe.";
    return json({ error: message }, 502);
  }

  return json({ url: stripePayload.url });
}

export default {
  async fetch(request, env, ctx) {
    void ctx;
    const url = new URL(request.url);

    if (url.pathname === "/api/create-checkout-session") {
      if (request.method !== "POST") return json({ error: "Método não permitido." }, 405);
      return createCheckoutSession(request, env);
    }

    if ((url.pathname === "/" || url.pathname === "/index.html") && request.method === "GET") {
      return response(page, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
    }
    if (url.pathname === "/styles.css" && request.method === "GET") {
      return response(styles, { headers: { "content-type": "text/css; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/script.js" && request.method === "GET") {
      return response(clientScript, { headers: { "content-type": "text/javascript; charset=utf-8", "cache-control": "public, max-age=3600" } });
    }
    if (url.pathname === "/health") return json({ ok: true });

    return response("Not found", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
  },
};
